<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, watch, nextTick } from 'vue'
import { api,newHost,newRule,endpoint,states,type Host,type Rule,type Plan,type State,type Config } from './api'
function clone<T>(value:T):T{return JSON.parse(JSON.stringify(value))}
const clipboard=navigator.clipboard
const state=ref<State|null>(null), page=ref('转发'), search=ref(''), error=ref(''), notice=ref(''), busy=ref(false)
const overrides=ref('')
const selected=ref<string[]>([]), expanded=ref<string[]>([]), optionsText=ref(''), dialog=ref<HTMLDialogElement|null>(null)
const hostDraft=ref<Host|null>(null), ruleDraft=ref<Rule|null>(null), planDraft=ref<Plan|null>(null), temporary=ref(false), adoptGroup=ref('')
const configDraft=ref(''), fileText=ref(''), filePath=ref(''), fileRevision=ref(''), keyPath=ref(''), keyData=ref<any>(null), observations=ref<any>(null)
const keyComment=ref(''), knownHost=ref('')
const preview=ref(''), answer=ref(''), promptId=ref(''), result=ref<any>(null)
const theme=ref('system'); let timer:ReturnType<typeof setInterval>; const media=matchMedia('(prefers-color-scheme: dark)')
function applyTheme(){document.documentElement.dataset.theme=theme.value==='system'?(media.matches?'dark':'light'):theme.value}
watch(theme,applyTheme); media.addEventListener('change',applyTheme)
const hosts=computed(()=>{const all=[...(state.value?.config.hosts??[])];if(page.value==='转发')for(const g of state.value?.groups??[]){if(!all.some(h=>h.id===g.hostId))all.push(g.snapshot.host)}return all.filter(h=>`${h.name} ${h.notes} ${h.category} ${h.destination}`.toLowerCase().includes(search.value.toLowerCase()))})
const currentPrompt=computed(()=>state.value?.prompts[0])
watch(()=>currentPrompt.value?.id,id=>{if(id!==promptId.value){answer.value='';promptId.value=id??'';void nextTick(()=>document.querySelector<HTMLInputElement>('#auth-answer')?.focus())}})
async function refresh(){try{state.value=await api<State>('status');if(!busy.value)theme.value=state.value.config.theme}catch(e){error.value=String(e)}}
async function run(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false;await refresh()}}
async function saveConfig(c:Config){await api('save',{config:c,revision:state.value?.revision})}
function cloneConfig(){return clone(state.value!.config)}
function open(kind:string, data?:Host|Rule|Plan){hostDraft.value=null;ruleDraft.value=null;planDraft.value=null;preview.value='';adoptGroup.value='';temporary.value=false;if(kind==='host'){hostDraft.value=data?clone(data as Host):newHost();optionsText.value=hostDraft.value.options.join('\n')}if(kind==='rule'){ruleDraft.value=data?clone(data as Rule):newRule(hosts.value[0]?.id)}if(kind==='temporary'){temporary.value=true;ruleDraft.value=newRule(hosts.value[0]?.id)}if(kind==='plan'){planDraft.value=data?clone(data as Plan):{id:crypto.randomUUID(),name:'',ruleIds:[],notes:'',autoStart:false}}dialog.value?.showModal()}
function option(name:string){return optionsText.value.split('\n').find(x=>x.toLowerCase().startsWith(name.toLowerCase()+'='))?.slice(name.length+1)??''}
function setOption(name:string,value:string){const lines=optionsText.value.split('\n');const i=lines.findIndex(x=>x.toLowerCase().startsWith(name.toLowerCase()+'='));if(i>=0){if(value)lines[i]=`${name}=${value}`;else lines.splice(i,1)}else if(value)lines.unshift(`${name}=${value}`);optionsText.value=lines.filter(Boolean).join('\n')}
function saveDraft(){void run(async()=>{let c=cloneConfig();if(hostDraft.value){hostDraft.value.options=optionsText.value.split('\n').filter(Boolean);const h=hostDraft.value;c.hosts=c.hosts.filter(x=>x.id!==h.id);c.hosts.push(h)}if(ruleDraft.value){const r=ruleDraft.value;if(temporary.value){result.value=await api('ensure',{request:{temporary:[r],consumer:'手动临时转发'}});dialog.value?.close();return}if(adoptGroup.value){await api('adopt',{groupId:adoptGroup.value,rule:r,revision:state.value!.revision});dialog.value?.close();return}c.rules=c.rules.filter(x=>x.id!==r.id);c.rules.push(r)}if(planDraft.value){const p=planDraft.value;c.plans=c.plans.filter(x=>x.id!==p.id);c.plans.push(p)}await saveConfig(c);dialog.value?.close();notice.value='已保存，运行连接保持现有参数'})}
function remove(kind:string,id:string){void run(async()=>{const c=cloneConfig();if(kind==='rule'){c.rules=c.rules.filter(r=>r.id!==id);c.plans.forEach(p=>p.ruleIds=p.ruleIds.filter(r=>r!==id))}if(kind==='plan')c.plans=c.plans.filter(p=>p.id!==id);if(kind==='host'){if(c.rules.some(r=>r.hostId===id))throw new Error('请先移除此主机下的规则登记');c.hosts=c.hosts.filter(h=>h.id!==id)}await saveConfig(c);notice.value='已移除登记，现有连接仍可按组停止'})}
function ensure(ids:string[],planId?:string){void run(async()=>{result.value=await api('ensure',{request:{ruleIds:ids,planId,overrides:overrides.value.split('\n').filter(Boolean),consumer:planId?`计划:${planId}`:'手动'}});notice.value=result.value.ready?'转发已就绪':'部分转发未就绪，请查看结果'})}
function stop(scope:string,id?:string){void run(()=>api('stop',{scope,id}))}
async function submitAnswer(){try{await api('answer',{id:currentPrompt.value?.id,answer:answer.value});answer.value='';await refresh()}catch(e){error.value=String(e)}}
function removeKnownHost(){if(window.confirm(`从 ${filePath.value} 删除 ${knownHost.value} 的主机指纹记录？`))void run(async()=>{preview.value=JSON.stringify(await api('knownHosts.remove',{path:filePath.value,host:knownHost.value,confirm:true}),null,2)})}
function saveTemporary(gid:string,r:Rule){open('rule',r);ruleDraft.value!.id=crypto.randomUUID();adoptGroup.value=gid}
function hostGroups(id:string){return state.value?.groups.filter(g=>g.hostId===id)??[]}
function hostRules(id:string){return state.value?.config.rules.filter(r=>r.hostId===id)??[]}
function ruleGroup(r:Rule){return state.value?.groups.find(g=>g.desired&&g.rules.some(x=>x.id===r.id))}
function pending(r:Rule){const g=ruleGroup(r);if(!g)return false;const old=g.rules.find(x=>x.id===r.id)!;const h=state.value?.config.hosts.find(h=>h.id===r.hostId);return ['hostId','direction','bind','port','target','targetPort'].some(k=>(r as any)[k]!== (old as any)[k])||Boolean(h&&['destination','ssh','configFile','options','reconnect','hidden'].some(k=>JSON.stringify((h as any)[k])!==JSON.stringify((g.snapshot.host as any)[k])))}
function toggle(id:string){expanded.value=expanded.value.includes(id)?expanded.value.filter(x=>x!==id):[...expanded.value,id]}
onMounted(async()=>{applyTheme();await refresh();timer=setInterval(()=>void refresh(),1000)})
onUnmounted(()=>{clearInterval(timer);media.removeEventListener('change',applyTheme)})
</script>
<template>
<div class="shell">
 <aside><div class="brand"><span class="mark">↔</span><strong>Tether</strong></div><nav aria-label="主要导航"><button v-for="p in ['转发','主机','计划','密钥','配置']" :key="p" :class="{active:page===p}" @click="page=p">{{ p }}</button></nav><label class="theme">外观<select v-model="theme" @change="run(async()=>{const c=cloneConfig();c.theme=theme as Config['theme'];await saveConfig(c)})"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></label></aside>
 <main :aria-busy="busy">
 <header><div><h1>{{ page }}</h1><span class="muted">{{ state?.config.hosts.length??0 }} 台主机 · {{ state?.groups.filter(g=>g.desired).length??0 }} 个托管连接组</span></div><button :disabled="busy" @click="run(refresh)">刷新</button></header>
 <div v-if="error||state?.configError" class="message error" role="alert">{{ error||state?.configError }}<button @click="run(()=>api('reload'))">重新加载配置</button></div>
 <div v-if="notice" class="message" role="status">{{ notice }}</div>
 <section v-if="currentPrompt" class="authentication" aria-labelledby="auth-title"><h2 id="auth-title">{{ currentPrompt.host }} · 等待认证</h2><pre>{{ currentPrompt.text }}</pre><form @submit.prevent="submitAnswer"><label>回答<input id="auth-answer" v-model="answer" :type="currentPrompt.secret?'password':'text'" autocomplete="off"></label><button class="primary">提交</button><button type="button" @click="api('cancelPrompt',{id:currentPrompt.id}).then(refresh)">取消操作</button></form></section>
 <template v-if="page==='转发'">
 <div class="toolbar"><input v-model="search" aria-label="搜索主机" placeholder="搜索主机、分组或备注"><button class="primary" :disabled="busy||!hosts.length" @click="open('rule')">新增转发</button><button :disabled="busy||!hosts.length" @click="open('temporary')">临时转发</button><button :disabled="busy||!selected.length" @click="ensure(selected)">启动所选 {{ selected.length||'' }}</button><button class="danger" :disabled="busy" @click="stop('all')">停止全部托管</button></div>
 <details class="temporary-options"><summary>本次启动覆盖</summary><label>有序 -o 选项（不保存到主机）<textarea v-model="overrides" rows="3" placeholder="每行 Name=Value"></textarea></label></details>
 <div v-if="!state?.config.hosts.length" class="empty"><h2>添加第一台 SSH 主机</h2><p>使用已有 SSH 别名，或填写目标地址。</p><button class="primary" @click="open('host')">添加主机</button></div>
 <section v-for="h in hosts" :key="h.id" class="host"><div class="host-heading"><div><h2>{{ h.name }} <small>{{ h.category }}</small></h2><p>{{ h.notes||h.destination }}<span v-if="!state?.config.hosts.some(x=>x.id===h.id)"> · 已移除登记，保留运行记录</span></p></div><div class="actions"><span class="latency" title="目标 SSH 地址 TCP 响应时间；跳板目标无数据">{{ state?.latency[h.id] != null ? `${state.latency[h.id]} ms` : '—' }}</span><button :disabled="busy" @click="run(()=>api('test',{hostId:h.id}))">测试</button><button :disabled="busy" @click="ensure(hostRules(h.id).map(r=>r.id))">启动主机规则</button><button class="danger" :disabled="busy" @click="stop('host',h.id)">停止此主机</button></div></div>
 <div v-for="g in hostGroups(h.id)" :key="g.id" class="group"><div class="group-heading"><button class="disclosure" :aria-expanded="expanded.includes(g.id)" @click="toggle(g.id)">{{ expanded.includes(g.id)?'▾':'▸' }} 连接 {{ g.id.slice(0,8) }} · {{ g.rules.length }} 项</button><span :class="['status',g.state]">{{ states[g.state]||g.state }}</span><button v-if="g.desired" class="danger" :disabled="busy" @click="stop('group',g.id)">停止整组（{{ g.rules.length }} 项）</button></div><p v-if="g.error" class="error inline">{{ g.error }}</p><div v-for="r in g.rules" :key="r.id" class="rule"><strong>{{ r.name }}</strong><code>{{ endpoint(r) }}</code><button v-if="!state?.config.rules.some(x=>x.id===r.id)&&!r.id.startsWith('ssh:')" :disabled="busy" @click="saveTemporary(g.id,r)">保存为规则</button><span v-if="r.notes" class="muted">{{ r.notes }}</span></div><div v-if="expanded.includes(g.id)" class="details"><p>使用方：{{ g.consumers.join('、')||'手动' }} · PID {{ g.pid??'—' }}</p><p>稳定身份：{{ g.id }}</p><pre>{{ JSON.stringify(g.args,null,2) }}</pre><pre class="logs">{{ g.logs.join('\n') }}</pre></div></div>
 <div v-for="r in hostRules(h.id)" :key="r.id" class="rule registered"><label><input v-model="selected" type="checkbox" :value="r.id"><strong>{{ r.name }}</strong></label><code>{{ endpoint(r) }}</code><span class="muted">{{ pending(r)?'参数待应用':ruleGroup(r)?'已关联连接组':'未启动' }}</span><div class="actions"><button :disabled="busy" @click="ensure([r.id])">启动 / 复用</button><button @click="open('rule',r)">编辑</button><button @click="remove('rule',r.id)">移除登记</button></div><p v-if="r.notes" class="muted">{{ r.notes }}</p></div>
 </section>
 <details class="external"><summary @click="()=>{if(!observations)run(async()=>{observations=await api('observe')})}">外部 SSH · 只读观测</summary><pre>{{ JSON.stringify(observations,null,2) }}</pre><button :disabled="busy" @click="run(async()=>{observations=await api('observe')})">更新观测</button></details>
 <details v-if="result" class="external" open><summary>本次启动结果</summary><ul><li v-for="r in result.results" :key="r.ruleId">{{ state?.config.rules.find(x=>x.id===r.ruleId)?.name||r.ruleId }}：{{ states[r.state]||r.state }} {{ r.reused?'· 已复用':'' }} {{ r.error }}</li></ul></details>
 </template>
 <template v-if="page==='主机'"><div class="toolbar"><button class="primary" @click="open('host')">添加主机</button></div><section v-for="h in hosts" :key="h.id" class="host"><div class="host-heading"><div><h2>{{ h.name }}</h2><p>{{ h.destination }} · {{ h.category }}</p><p>{{ h.notes }}</p><code>{{ h.id }}</code></div><div class="actions"><button @click="open('host',h)">编辑主机</button><button @click="run(async()=>{preview=JSON.stringify(await api('preview',{hostId:h.id}),null,2)})">生效参数</button><button @click="remove('host',h.id)">移除登记</button></div></div></section><pre v-if="preview" class="preview">{{ preview }}</pre></template>
 <template v-if="page==='计划'"><div class="toolbar"><button class="primary" @click="open('plan')">新建计划</button></div><p v-if="!state?.config.plans.length" class="empty">将多条规则保存为一份启动清单。</p><section v-for="p in state?.config.plans" :key="p.id" class="host"><div class="host-heading"><div><h2>{{ p.name }} <small v-if="p.autoStart">后台启动时执行</small></h2><p>{{ p.notes }} · {{ p.ruleIds.length }} 项规则</p><code>{{ p.id }}</code></div><div class="actions"><button class="primary" :disabled="busy" @click="ensure([],p.id)">启动计划</button><button @click="open('plan',p)">编辑</button><button @click="remove('plan',p.id)">移除计划</button></div></div></section><pre v-if="result" class="preview">{{ JSON.stringify(result,null,2) }}</pre></template>
 <template v-if="page==='密钥'"><div class="toolbar"><button :disabled="busy" @click="run(async()=>{keyData=await api('keys.list')})">刷新密钥与 Agent</button></div><form class="panel" @submit.prevent="run(async()=>{const c=cloneConfig();if(!c.keyFiles.includes(keyPath))c.keyFiles.push(keyPath);await saveConfig(c);notice='密钥路径已登记'})"><label>密钥文件的绝对路径<input v-model="keyPath" required placeholder="C:/Users/you/.ssh/id_ed25519"></label><button>登记路径</button><button type="button" @click="run(()=>api('keys.generate',{path:keyPath,algorithm:'ed25519'}))">在新路径生成 Ed25519 密钥</button></form><section v-for="p in state?.config.keyFiles" :key="p" class="host"><code>{{ p }}</code><div class="actions"><button @click="run(async()=>{const r=await api<{publicKey:string}>('keys.public',{path:p});await clipboard.writeText(r.publicKey);notice='公钥已复制'})">复制公钥</button><button @click="run(()=>api('agent.add',{path:p}))">加载 Agent</button><button @click="run(()=>api('agent.remove',{path:p}))">移出 Agent</button><button @click="run(()=>api('keys.passphrase',{path:p}))">修改口令</button></div></section><section class="panel"><label>公钥备注<input v-model="keyComment"></label><label>已登记的私钥路径<select v-model="keyPath"><option value="">选择文件</option><option v-for="p in state?.config.keyFiles.filter(p=>!p.endsWith('.pub'))" :key="p" :value="p">{{ p }}</option></select></label><button :disabled="busy||!keyPath" @click="run(()=>api('keys.comment',{path:keyPath,comment:keyComment}))">保存公钥备注</button></section><pre v-if="keyData" class="preview">{{ JSON.stringify(keyData,null,2) }}</pre></template>
 <template v-if="page==='配置'"><p class="muted break">{{ state?.configPath }}</p><details class="panel"><summary @click="configDraft=JSON.stringify(state?.config,null,2)">本地配置 · 原始 JSON</summary><label>规则、计划、文件引用和设备设置<textarea v-model="configDraft" rows="18" spellcheck="false"></textarea></label><button :disabled="busy" @click="run(async()=>{await saveConfig(JSON.parse(configDraft));notice='配置已保存'})">保存本地配置</button></details><section class="panel"><h2>SSH 原文与 known_hosts</h2><p class="muted">在本地配置的 sshFiles 登记路径后，可读写原文。保存会检测外部修改并创建备份。</p><label>文件绝对路径<input v-model="filePath" list="ssh-files"><datalist id="ssh-files"><option v-for="p in state?.config.sshFiles" :key="p" :value="p" /></datalist></label><button :disabled="busy" @click="run(async()=>{const r=await api<any>('files.read',{path:filePath});fileText=r.text;fileRevision=r.revision})">读取原文</button><label>原始内容<textarea v-model="fileText" rows="16" spellcheck="false"></textarea></label><button :disabled="busy||!fileRevision" @click="run(async()=>{const r=await api<any>('files.write',{path:filePath,text:fileText,revision:fileRevision});fileRevision=r.revision;notice=`已保存；备份 ${r.backup}`})">保存原文与备份</button></section><section class="panel"><h2>主机指纹</h2><p class="muted">使用上方登记的 known_hosts 路径，只修改本机记录。</p><label>主机或 [主机]:端口<input v-model="knownHost"></label><button :disabled="busy||!knownHost||!filePath" @click="run(async()=>{preview=JSON.stringify(await api('knownHosts.find',{path:filePath,host:knownHost}),null,2)})">查找指纹</button><button class="danger" :disabled="busy||!knownHost||!filePath" @click="removeKnownHost">删除此主机记录</button><pre v-if="preview">{{ preview }}</pre></section></template>
 </main>
 <dialog ref="dialog" @click="e=>{if(e.target===dialog)dialog?.close()}"><form @submit.prevent="saveDraft"><h2>{{ hostDraft?'主机':planDraft?'启动计划':temporary?'临时转发':adoptGroup?'保存运行转发':'转发规则' }}</h2>
 <template v-if="hostDraft"><label>名称<input v-model="hostDraft.name" required></label><label>SSH 别名或目标<input v-model="hostDraft.destination" required placeholder="user@server 或 SSH 别名"></label><label>分组<input v-model="hostDraft.category"></label><label>SSH 配置路径（留空使用原生默认）<input :value="hostDraft.configFile??''" @input="hostDraft.configFile=($event.target as HTMLInputElement).value||null"></label><div class="fields"><label>SSH 用户<input :value="option('User')" placeholder="继承 SSH 配置" @input="setOption('User',($event.target as HTMLInputElement).value)"></label><label>SSH 端口<input :value="option('Port')" type="number" min="1" max="65535" placeholder="继承" @input="setOption('Port',($event.target as HTMLInputElement).value)"></label></div><label>身份文件（更多身份可在高级选项中逐行添加）<input :value="option('IdentityFile')" placeholder='路径含空格时使用双引号' @input="setOption('IdentityFile',($event.target as HTMLInputElement).value)"></label><label>跳板链<input :value="option('ProxyJump')" placeholder="jump1,jump2" @input="setOption('ProxyJump',($event.target as HTMLInputElement).value)"></label><div class="fields"><label>保活间隔（秒）<input :value="option('ServerAliveInterval')" type="number" min="0" placeholder="15" @input="setOption('ServerAliveInterval',($event.target as HTMLInputElement).value)"></label><label>地址族<select :value="option('AddressFamily')" @change="setOption('AddressFamily',($event.target as HTMLSelectElement).value)"><option value="">继承</option><option value="any">自动</option><option value="inet">IPv4</option><option value="inet6">IPv6</option></select></label></div><details><summary>高级 SSH 参数</summary><label>程序<input v-model="hostDraft.ssh" required></label><label>有序 -o 选项（每行 Name=Value）<textarea v-model="optionsText" rows="7" placeholder="User=admin&#10;Port=22&#10;IdentityFile=C:/Users/you/.ssh/key&#10;ProxyJump=jump"></textarea></label><p class="muted">每行原样传给 OpenSSH，首次值优先；托管进程与就绪所需选项由 Tether 控制。</p><label>认证和就绪超时（秒）<input v-model.number="hostDraft.timeoutSecs" type="number" min="1" max="120"></label><label class="check"><input v-model="hostDraft.reconnect" type="checkbox">断线后重连</label><label class="check"><input v-model="hostDraft.hidden" type="checkbox">隐藏本地控制台</label></details><label>备注<textarea v-model="hostDraft.notes" rows="2"></textarea></label></template>
 <template v-if="ruleDraft"><label>名称<input v-model="ruleDraft.name" required></label><label>主机<select v-model="ruleDraft.hostId" required><option v-for="h in state?.config.hosts" :key="h.id" :value="h.id">{{ h.name }}</option></select></label><label>方向<select v-model="ruleDraft.direction"><option value="local">本地转发（目标由远端连接）</option><option value="remote">远程转发（目标由本机连接）</option><option value="dynamic">动态 SOCKS</option></select></label><div class="fields"><label>监听地址<input v-model="ruleDraft.bind"></label><label>监听端口<input v-model.number="ruleDraft.port" required type="number" min="1" max="65535"></label></div><div v-if="ruleDraft.direction!=='dynamic'" class="fields"><label>目标地址<input v-model="ruleDraft.target" required></label><label>目标端口<input v-model.number="ruleDraft.targetPort" required type="number" min="1" max="65535"></label></div><label>备注<textarea v-model="ruleDraft.notes" rows="2"></textarea></label><p class="muted break">稳定规则 ID：{{ ruleDraft.id }}</p></template>
 <template v-if="planDraft"><label>名称<input v-model="planDraft.name" required></label><label>备注<textarea v-model="planDraft.notes" rows="2"></textarea></label><fieldset><legend>规则</legend><label v-for="r in state?.config.rules" :key="r.id" class="check"><input v-model="planDraft.ruleIds" type="checkbox" :value="r.id">{{ r.name }} · {{ r.port }}</label></fieldset><label class="check"><input v-model="planDraft.autoStart" type="checkbox">每次后台启动时执行此计划</label></template>
 <footer><button type="button" @click="dialog?.close()">取消</button><button class="primary" :disabled="busy">{{ temporary?'启动临时转发':'保存' }}</button></footer></form></dialog>
</div>
</template>
